      child.on('error',e=>{clearTimeout(timeout);reject(e);});
      child.on('close',code=>{clearTimeout(timeout);if(code!==0)return reject(new Error(`Codex request failed: ${stderr.slice(-500)}`));const items=stdout.split('\n').flatMap(line=>{try{return [JSON.parse(line)];}catch{return [];}});const message=items.filter(e=>e.type==='item.completed'&&e.item?.type==='agent_message').at(-1)?.item?.text;if(!message)return reject(new Error('Codex did not return a structured answer'));resolve(message);});
